package transpile

import (
	"strings"
	"testing"
)

func TestCCoreSyntax(t *testing.T) {
	got, err := C(`
let add = fn(a, b) { return a + b }
let value = add(1, 2)
if true { value = value + 1 }
`, "test.doml")
	if err != nil {
		t.Fatal(err)
	}
	for _, want := range []string{
		"/* Generated by domscript -T c; ANSI C */",
		"static double add(double a, double b)",
		"return (a + b);",
		"double value = add(1, 2);",
		"if (1)",
		"int main(void)",
	} {
		if !strings.Contains(got, want) {
			t.Errorf("output missing %q:\n%s", want, got)
		}
	}
}

func TestCRejectsInvalidSource(t *testing.T) {
	if _, err := C("let =", "test.doml"); err == nil {
		t.Fatal("expected syntax error")
	}
}
